"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "铜管乐器有小号、圆号、大号、军号、号角。木管乐器有笛子、长笛、萨克斯管、单簧管、巴松管、巴拉班和唢呐。",
"Клавишные духовые": "键盘管乐器",
