"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "这是指话剧、音乐会或演出中的声音和灯光配合，以及动作和变化的幻象。这个词来自拉丁语，意思是“执行、表演”。",
