"Музыкальная живопись": "音乐绘画",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "人们总爱分享自己看到和听到的感受。甚至有一种说法叫“音乐绘画”——就是描绘大自然画面的音乐。",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "柴可夫斯基的组曲《四季》由12首小曲组成。每首小曲都是一年中某个月份的形象，大多通过风景来表现。",
"Настроение сезона": "季节的情绪",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "在这些水彩画般的小曲中，表现了季节的情绪：冬天的梦幻、春天的清新、夏天的辽阔、秋天的忧伤。",
"Программная музыка": "标题音乐",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "这是没有歌词的古典音乐，也就是器乐曲。但它附有对内容的文字说明：标题或解说。",
"Заголовок и эпиграф": "标题和题词",
