"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "号召就是呼唤人们行动的呼吁。哈萨克语叫“шакыру”，英语叫“call”。",
"Музыка, которая зовёт": "会呼唤的音乐",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "许多音乐作品不只是装点我们的生活。它们成为行动的指南，帮助人做出正确的选择。",
"Экологическая тема": "环保主题",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "音乐中有环保主题——就是保护环境。歌曲提醒我们，要爱护大自然。",
"«Песня о земной красоте»": "《大地之美之歌》",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "这首歌是杜布拉温写的。它讲的是大自然的美，以及要与人分享的善良。",
"«Не дразните собак»": "《不要逗狗》",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "这首歌出自电影《事件》。曲作者是皮奇金，词作者是普利亚茨科夫斯基。歌曲号召人们善待动物，珍惜大地的美。",
"Береги природу": "爱护大自然",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "巴尔西克问：什么对大自然和动物有帮助，什么对它们有害？请把卡片分类。",
