"Мой любимец": "我心爱的小动物",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "能解释什么是乐谱改编，并说出关于心爱动物的音乐作品。",
"Конь в музыке": "音乐中的马",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "对哈萨克民族来说，最受喜爱和尊敬的动物一直是马，是骏马。许多作曲家用音乐描绘它飞奔不停的疾驰。",
"Курмангазы и «Адай»": "库尔曼加兹和《阿代》",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "伟大的哈萨克作曲家库尔曼加兹创作了音乐画卷《阿代》。其中不只是疾驰：他展现了古老的哈萨克阿代部落勇敢、英雄的精神。",
"Одно произведение — разное исполнение": "同一首作品，不同的演奏",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "库依《阿代》有三种演奏可以听：用冬不拉、用乐队、用电子乐器。作品只有一首，演奏却各不相同。",
"Что такое переложение": "什么是改编",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "改编就是用另一种形式表现的音乐作品。巴尔西克说：旋律还是那个旋律，听起来却是新的！",
"Песни о любимцах и о мире": "关于心爱小动物和世界的歌",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "世界各民族都有关于家养宠物的歌，例如英国民歌《小猫咪和手套》。而克温特的歌曲《你好，世界》讲的是小马驹和周围的世界。“世界”这个词，哈萨克语是әлем。",
"Чья это песня или кюй?": "这是谁的歌或库依？",
