"17-сабақ. Музыкадағы таң көріністері": "第17课：音乐中的黎明景象",
"Музыкадағы таң көріністері": "音乐中的黎明景象",
"Музыкадағы таң көріністерін сипаттап, М. Мусоргскийдің, Э. Григтің және С. Еркімбековтің шығармаларын ажырата білу.": "能够描述音乐中的黎明景象，并分辨穆索尔斯基、格里格和叶尔金别科夫的作品。",
"Композиторға не әсер етеді?": "是什么影响着作曲家？",
"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "作曲家的创作来自灵感、想象力，以及对故乡、对人民和对大自然的热爱。我们用语言说出自己的爱，他们则用音乐来讲述。",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "莫杰斯特·彼得罗维奇·穆索尔斯基（1839–1881）是俄罗斯伟大的作曲家。他因为歌剧《霍万斯基党人》的序曲《莫斯科河上的黎明》而闻名：其中描绘了朝霞满天的黎明。",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "爱德华·格里格（1843–1907）是挪威著名的作曲家、钢琴家和指挥家。他在《培尔·金特》组曲中的《晨曲》里，用艺术手法描绘了故乡的自然风光和晨光。",
"С. Еркімбеков": "谢·叶尔金别科夫",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "谢里克·叶尔金别科夫是著名作曲家，哈萨克斯坦共和国功勋艺术家。他的作品《祖国的黎明》展现了故乡的美丽。",
"Жаңа сөздер": "新词语",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "歌剧是把声乐、器乐和戏剧艺术结合在一起的体裁。组曲是由服从同一个构思的不同小曲组成的作品。诠释是演奏者对作品的艺术解读。",
