"Айту: А.Н. Скрябиннің «Прометей» симфониялық поэмасы мен «Жалын биі», «Жел» шығармаларында от пен жел қалай бейнеленетінін түсіндіру.": "讲一讲：在斯克里亚宾的交响诗《普罗米修斯》以及《火焰之舞》《风》这些作品中，火和风是怎样被表现出来的。",
"От — өмір символы": "火是生命的象征",
"Адам отсыз өмір сүре алмайды. От ежелден өмірдің және жылулықтың символы болып саналады.": "人没有火就无法生存。自古以来，火就被看作生命和温暖的象征。",
"«Прометей» поэмасы": "交响诗《普罗米修斯》",
"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "这是斯克里亚宾的一部交响诗。它的另一个名字是《火之诗》。它写于1910年。",
"Прометей туралы аңыз": "普罗米修斯的传说",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "这首诗取材于古希腊的传说。普罗米修斯未经允许从奥林匹斯山取走了火，送给了人类。为此，众神把他永远绑在了岩石上。",
"Жарық партиясы": "光的声部",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "斯克里亚宾在管弦乐队里加入了合唱和“光的声部”。按照作曲家的想法，随着音乐，各色探照灯的光束要不断变换。",
"Симфониялық поэма": "交响诗",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "交响诗是单乐章的交响音乐体裁。它是为管弦乐队写的标题音乐作品。",
