"Музыкадағы табиғат құбылыстары (жалғасы)": "音乐中的自然现象（续）",
"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "能够通过音乐想象水和风的形象，并把作品与画作和舞蹈进行比较。",
"Су мен жел – табиғат құбылыстары": "水和风是自然现象",
"«Сусыз өмір жоқ», «Жел ауа тазартады» дейді. Әр табиғат құбылысының адам өмірінде өз орны бар.": "人们说“没有水就没有生命”“风能净化空气”。每一种自然现象在人的生活中都有它的位置。",
