"«Жел» әнінің өлеңін Н. Әлімқұлов, әнін М. Маңғытаев жазған. Оны мәнерлеп орындауға тырысамыз.": "歌曲《风》的歌词是阿里姆库洛夫写的，曲子是曼吉塔耶夫谱的。我们要努力有表情地演唱它。",
