"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "能够说出维瓦尔第的四季协奏曲，以及有关管弦乐队的基本概念（管弦乐队、指挥、总谱、协奏曲）。",
"Жылдың төрт мезгілі": "一年的四个季节",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "冬、春、夏、秋依次轮换。每个季节都有自己的美，所以人们为它写了诗歌、歌曲和音乐作品。",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "维瓦尔第（1678–1741）是意大利作曲家，技艺高超的小提琴家，也是指挥家。他出生在威尼斯。",
