"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "维瓦尔第最著名的作品是名为《四季》的四首小提琴协奏曲。它们是：《春》《夏》《秋》《冬》。",
"«Шат көңіл» әні": "歌曲《快乐的心情》",
"Бұл әннің өлеңін Б. Тәжібаев жазған, әнін С. Еркімбеков шығарған. Ән вальс ырғағымен орындалады, көңілді, жарқын.": "这首歌的歌词是塔日巴耶夫写的，曲子是叶尔金别科夫谱的。歌曲用华尔兹的节奏演唱，欢快明朗。",
