"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "认识关于四季的作品，讲解卡农、管弦乐队、指挥、交响诗和组曲这些概念。",
"Жыл – он екі ай": "一年——十二个月",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "有很多关于四季的歌曲和乐曲。冬不拉演奏家、作曲家托列别尔根·托克扎诺夫为冬不拉写了《一年——十二个月》系列小曲，曲中描绘了十二个月各自的特点。",
"«Жұмбақ әуендер» ойыны": "“神秘旋律”游戏",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "根据听到的音乐，用颜色相符的纸片指出作品的名称：《二月——暴风雪》——白色，《九月——秋日盛会》——黄色，《四月——春天的水滴》——绿色，《七月——夏日之舞》——红色。正确指出颜色的小组获胜。",
"Канон": "卡农",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "演唱歌曲的一种方式是卡农。把歌曲分成几个小组，各组轮流一个接一个地开始唱歌节。《下雨吧，下雨吧！》这首歌的词由沙·萨里耶夫写，曲由克·杜伊塞克耶夫谱写。",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "乐队是用各种乐器演奏作品的集体。指挥是领导演奏家集体的专业人员。",
