"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "交响诗是为交响乐队创作的单乐章标题作品。组曲是服从于同一个构思、由不同小曲组成的音乐作品。",
