"22-сабақ. Арал тағдыры — ел тағдыры": "第22课：咸海的命运——国家的命运",
"Арал тағдыры — ел тағдыры": "咸海的命运——国家的命运",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "能借助音乐和绘画讲述咸海问题，并能区分克·赛扬的库依曲、塔·舍甫琴科的风景画和歌曲《我的咸海》。",
"Арал мәселесі": "咸海问题",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "咸海正在干涸。风吹起的苦咸盐对大自然和人体健康都有害。",
"Бүкіл әлемнің қайғысы": "全世界的悲痛",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "咸海问题不仅对哈萨克斯坦重要，对其他国家也同样迫切。国内外的科学家正在研究让咸海重新充满水的办法。",
"«Арал тағдыры» күйі": "库依曲《咸海的命运》",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "这是克·赛扬的库依曲。库依的演奏表达了人悲伤、哀痛的情感，作曲家努力向听众传达一个重要的思想。",
"Тарас Шевченко": "塔拉斯·舍甫琴科",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "塔拉斯·格里戈里耶维奇·舍甫琴科（1814–1861）是乌克兰著名诗人兼画家。1838年毕业于圣彼得堡美术学院。",
"Шевченко және Арал": "舍甫琴科与咸海",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "1848年，他在阿·伊·布塔科夫的领导下参加了考察咸海的考察队，画了350多幅风景画和肖像画。曼吉斯套州图普卡拉甘区的中心叫作“舍甫琴科要塞”。",
