"Ғазиза Жұбанова": "加济扎·朱巴诺娃",
"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "加济扎·朱巴诺娃（1927–1993）是作曲家。她出生在阿拉木图市的一个音乐家庭。父亲是著名作曲家艾哈迈特·朱巴诺夫。",
"Композитордың шығармалары": "作曲家的作品",
