"Балет": "芭蕾舞",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "芭蕾舞是音乐与舞蹈相结合的舞台演出。它的内容、人物的思想感情通过音乐和舞蹈来表现。",
