"Ғ. Жұбанова тек ән жазған, балет жазбаған.": "加·朱巴诺娃只写歌曲，没有写芭蕾舞剧。",
"«Хиросима» балеті үшін Ғ. Жұбановаға Мемлекеттік сыйлық берілді.": "因芭蕾舞剧《广岛》，加·朱巴诺娃获得了国家奖。",
"Балет — музыка мен би арқылы мазмұнды көрсететін қойылым.": "芭蕾舞是通过音乐和舞蹈来表现内容的演出。",
"Реквием — көңілді, ойнақы музыкалық шығарма.": "安魂曲是欢快、活泼的音乐作品。",
"Балетте тек бір отбасының ғана емес, бүкіл халықтың қайғысы бейнеленген.": "芭蕾舞剧表现的不只是一个家庭的悲痛，而是整个民族的悲痛。",
"«Сакура» — қазақтың халық әні.": "《樱花》是哈萨克民歌。",
"Сакура ағашы көктемде нәзік гүл ашады.": "樱花树在春天绽放娇嫩的花朵。",
"Балеттің соңында жер бетінде ешқашан ядролық жарылыстар болмасын деген тілек айтылады.": "芭蕾舞剧的结尾表达了希望地球上永远不再发生核爆炸的心愿。",
"«Хиросима» балетінің кейіпкерлері — әке Тайо, ана және қызы Юки.": "芭蕾舞剧《广岛》的人物是父亲泰奥、母亲和女儿由纪。",
