"25-сабақ. Ел қорғауға дайынбыз!": "第25课：我们时刻准备保卫祖国！",
"Ел қорғауға дайынбыз!": "我们时刻准备保卫祖国！",
"Атап айту: «Сарбаздар жыры» мен «Мәңгілік алау» балетінің авторларын, тақырыбын және ел қорғау туралы музыканың мәнін түсіндіру.": "说一说：《战士之歌》和芭蕾舞剧《永恒的火焰》的作者和主题，并解释保卫祖国的音乐的意义。",
"Ата-бабалар аманаты": "先辈的嘱托",
"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "无论我们是谁，无论走到哪里，都应当爱护并保卫自己的故乡和大自然。这是先辈留给我们的嘱托。",
"Табиғатты қорғау": "保护大自然",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "在以前的课上，我们了解了咸海和塞米伊核试验场的问题。我们国土的自然环境正在受到损害，所以我们应当时刻准备保卫祖国和周围的环境。",
"«Сарбаздар жыры»": "《战士之歌》",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "这是一首关于哈萨克战士的歌曲。歌词由A.阿斯勒别克写作，曲子由N.艾特巴耶娃创作。歌曲里有副歌。",
"Әннің тақырыбы": "歌曲的主题",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "《战士之歌》赞美保卫祖国的勇敢战士。歌曲表达了对和平安宁生活的向往。",
"«Мәңгілік алау» балеті": "芭蕾舞剧《永恒的火焰》",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "这是一部独幕芭蕾舞剧的选段，音乐由S.叶尔金别科夫创作。这部芭蕾舞剧共有12个曲目，讲述战争与和平。其中一个曲目是《安魂曲》。",
