"26-сабақ. Қоршаған ортамызды сақтайық!": "第26课：让我们保护我们的环境！",
"Қоршаған ортамызды сақтайық!": "让我们保护我们的环境！",
"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "说出保护环境的职业，认识歌曲《故乡》和芭蕾舞剧《永恒的火焰》，并解释“人物”和“场景”的概念。",
"«Атамекен» әні": "歌曲《故乡》",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "这首歌的歌词由Sh.萨里耶夫写作，曲子由Zh.图亚克巴耶夫创作。歌曲赞美我们祖国美丽的大自然。",
"Төрт топ, төрт мамандық": "四个小组，四种职业",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "课上同学们分成四个小组：生态学家、消防员、渔民和护林员。每个小组准备介绍自己的职业。",
"Экологтер мен өртсөндірушілер": "生态学家和消防员",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "生态学家帮助人们与环境和谐相处。消防员日夜守护大家远离危险和灾难，发生火灾时赶来救援。",
"Балықшылар мен орманшылар": "渔民和护林员",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "渔民了解鱼的特性，并保持鱼类生长的水域清洁。护林员保护森林，承担各种各样的任务。",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "这部芭蕾舞剧的音乐是S.叶尔金别科夫写的。芭蕾是音乐与舞蹈相结合的表演。其中的人物不说话，而是通过舞蹈和音乐表达自己的想法。",
